"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[275],{127:(e,a,i)=>{function o(e){let a=e.display?.profile;return{sector:a?.sector||e.profile.sector||null,industry:a?.industry||e.profile.industry||null,country:a?.country||e.profile.country||null}}function n(e){let a=(e??"").trim();return a.length>1&&a[1]===a[1].toLowerCase()&&a[1]!==a[1].toUpperCase()?a[0].toLowerCase()+a.slice(1):a}i.d(a,{C:()=>o,m:()=>n})},3297:(e,a,i)=>{i.d(a,{L:()=>o,V:()=>n});let o={quality:{title:"Calidad del negocio",description:"Puntuaci\xf3n de 0 a 100 de la calidad del negocio: solidez financiera, rentabilidad, calidad de ganancias y crecimiento. El atractivo del precio se punt\xfaa aparte.",tip:"La calidad y el precio son preguntas distintas: una empresa excelente puede estar cara."},price:{title:"Atractivo del precio",description:"Puntuaci\xf3n de 0 a 100 de lo atractivo que es el precio actual: valoraci\xf3n por m\xfaltiplos frente a su referencia y DCF. Se contrae hacia 50 cuando la confianza del veredicto no es alta.",tip:"Si la confianza no es alta ver\xe1s \xabsin ajustar X → ajustado a Y\xbb: X es lo que dicen los m\xe9todos e Y la cifra ajustada por la confianza."},category:{title:"Categor\xedas de la puntuaci\xf3n",description:"Cada categor\xeda parte de una base neutral de 10/20 y suma o resta seg\xfan la banda en la que cae cada indicador. Solidez, Rentabilidad, Calidad de ganancias y Crecimiento forman la calidad del negocio; Valoraci\xf3n, el atractivo del precio.",tip:"Una categor\xeda \xabno concluyente\xbb no tiene datos suficientes: se excluye y la puntuaci\xf3n se calcula con las dem\xe1s."},confidence:{title:"Confianza del veredicto",description:"Mide cu\xe1nto fiarse del veredicto de precio: si los m\xe9todos de valoraci\xf3n coinciden, si hay datos suficientes, la calidad de la fuente y la estabilidad del tipo de empresa.",tip:"La confianza contrae el atractivo del precio hacia 50; la calidad del negocio, solo si la confianza es baja."},confidence_adjustment:{title:"Ajuste por confianza",description:"Cuando la confianza del veredicto no es alta, el atractivo del precio se acerca a 50 (neutral): la primera cifra es la que dan los m\xe9todos y la segunda, la ajustada.",tip:"Solo se ajusta el precio; la calidad del negocio no se toca."},cat_solidez:{title:"Solidez financiera",description:"Categor\xeda de la calidad del negocio que mide si la empresa puede pagar lo que debe y aguantar un mal a\xf1o: liquidez a corto plazo, endeudamiento frente a su sector, cobertura de intereses y riesgo de insolvencia (Altman).",tip:"En bancos y aseguradoras se mide con su salud financiera; en empresas que a\xfan no ganan dinero, con los meses de caja."},cat_rentabilidad:{title:"Rentabilidad",description:"Categor\xeda de la calidad del negocio que mide cu\xe1nto gana la empresa con lo que tiene: ROE, ROA, m\xe1rgenes y rentabilidad del capital invertido (ROIC) frente a su coste (WACC), cada uno frente a su sector."},cat_calidad_ganancias:{title:"Calidad de ganancias",description:"Categor\xeda de la calidad del negocio que mide si el beneficio contable se convierte en caja: Piotroski F-Score, flujo operativo y flujo de caja libre positivos, y flujo de caja libre frente al beneficio neto.",tip:"En bancos se mide con la estabilidad del ROE, la eficiencia y el crecimiento del valor en libros; en REIT, con el dividendo cubierto por el FFO."},cat_crecimiento:{title:"Crecimiento",description:"Categor\xeda de la calidad del negocio que mide cu\xe1nto han crecido los ingresos, el beneficio por acci\xf3n y el flujo de caja libre en los \xfaltimos tres a\xf1os."},cat_valoracion:{title:"Valoraci\xf3n",description:"Categor\xeda que da el atractivo del precio: los m\xfaltiplos frente a su referencia y el DCF suman o restan puntos sobre una base neutral."},pb_block:{title:"Bloque P/B y P/TBV",description:"Precio sobre valor en libros y sobre valor en libros tangible, que punt\xfaan juntos: en bancos y aseguradoras sustituyen a los m\xfaltiplos de beneficio y de caja."},pb_roe:{title:"P/B frente al ROE regulado",description:"En una utility, el precio sobre valor en libros se lee frente a la rentabilidad que el regulador le permite: pagar m\xe1s que el valor en libros solo se justifica con un ROE alto."},reverse_dcf:{title:"DCF inverso",description:"En lugar de estimar un valor, calcula qu\xe9 crecimiento descuenta el precio actual y lo compara con el que la empresa ha logrado y con el de empresas comparables.",tip:"Es el DCF que punt\xfaa cuando el directo no es fiable para el tipo de empresa."},conf_convergence:{title:"Convergencia entre m\xe9todos",description:"Si los m\xe9todos de valoraci\xf3n (m\xfaltiplos, DCF y los dem\xe1s que apliquen) apuntan en la misma direcci\xf3n y con una magnitud parecida."},conf_coverage:{title:"Cobertura de datos",description:"Qu\xe9 parte de los indicadores que aplican a la empresa tiene dato. Con huecos, el veredicto se apoya en menos."},conf_source:{title:"Calidad de fuente",description:"Si los datos usados pasaron la validaci\xf3n sin incidencias: cifras imposibles, unidades mal puestas o saltos que no cuadran."},conf_stability:{title:"Estabilidad del arquetipo",description:"Si el tipo de empresa (madura, crecimiento, banco…) es claro y sus resultados estables. Baja en una c\xedclica, cuyos resultados dependen de la fase del ciclo; media si la clasificaci\xf3n est\xe1 en el l\xedmite entre dos tipos."},conf_fuente_oficial:{title:"Fuente oficial (SEC)",description:"Si los estados financieros vienen de la SEC (EDGAR). Sin ellos, el an\xe1lisis usa cifras de proveedores sin contrastar y la confianza queda en baja."},price_now:{title:"Precio",description:"\xdaltimo precio de cotizaci\xf3n disponible."},market_cap:{title:"Capitalizaci\xf3n de mercado",description:"Valor total de la empresa en bolsa.",formula:"Precio \xd7 acciones en circulaci\xf3n",tip:"Las empresas m\xe1s grandes tienden a ser m\xe1s estables, con menos potencial de crecimiento explosivo."},beta:{title:"Beta bruta (volatilidad)",description:"Cu\xe1nto se mueve la acci\xf3n cuando se mueve el mercado (S&P 500), tal como la publica la fuente. Una beta igual a la unidad se mueve como el mercado. El coste de capital usa la beta ajustada (Blume), que ver\xe1s en el desglose del WACC.",formula:"Covarianza(acci\xf3n, mercado) / varianza(mercado)",tip:"Mide riesgo de mercado, no riesgo del negocio: una empresa d\xe9bil puede tener beta baja."},beta_blume:{title:"Beta ajustada (Blume)",description:"Cu\xe1nto se mueve la acci\xf3n cuando se mueve el mercado, medida con dos a\xf1os de rendimientos semanales frente al S&P 500 y acercada a la del mercado con el ajuste de Blume, porque las betas tienden a volver hacia la unidad con el tiempo. Es la que usa el coste de capital; la beta bruta est\xe1 en el desglose del WACC.",formula:"Beta ajustada = ⅔ \xd7 beta bruta + ⅓ \xd7 1",tip:"Mide riesgo de mercado, no riesgo del negocio: una empresa d\xe9bil puede tener beta baja."},beta_industry:{title:"Beta de la industria",description:"La beta propia de la acci\xf3n no pasa los filtros de la regresi\xf3n, as\xed que el coste de capital usa la de su industria (Damodaran), reapalancada con la deuda de la empresa cuando hay datos para hacerlo y sin ajuste de Blume. El detalle est\xe1 en el desglose del WACC.",tip:"Mide riesgo de mercado, no riesgo del negocio: una empresa d\xe9bil puede tener beta baja."},momentum:{title:"Momentum 12-1",description:"Rentabilidad de la acci\xf3n en los doce meses anteriores, sin contar el \xfaltimo mes. Mide si el mercado la viene premiando o castigando; el \xfaltimo mes se excluye porque suele darse la vuelta.",tip:"Es contexto de mercado: no punt\xfaa en la calidad ni en el precio."},trend:{title:"Tendencia (200 sesiones)",description:"Si el precio cotiza por encima o por debajo de su media de las \xfaltimas 200 sesiones (unos diez meses) y si esa media sube o baja.",tip:"Es contexto de mercado: no punt\xfaa en la calidad ni en el precio."},volatility:{title:"Volatilidad (1 a\xf1o)",description:"Cu\xe1nto oscila el precio de un d\xeda a otro, en tasa anual, comparado con el S&P 500 en el mismo a\xf1o."},drawdown:{title:"Ca\xedda m\xe1xima",description:"La mayor ca\xedda desde un m\xe1ximo hasta el m\xednimo siguiente en el \xfaltimo a\xf1o (y en la serie entera)."},volume:{title:"Volumen (\xfaltimas 5 sesiones)",description:"Si en la \xfaltima semana se negociaron m\xe1s o menos acciones de lo habitual, medido en desviaciones frente a las 90 sesiones anteriores (z)."},pead:{title:"Resultados y deriva (PEAD)",description:"C\xf3mo se movi\xf3 la acci\xf3n frente al S&P 500 alrededor de los \xfaltimos resultados trimestrales y en los d\xedas siguientes, y si el beneficio sorprendi\xf3 frente al consenso.",tip:"PEAD: deriva tras el anuncio de resultados, la tendencia del precio a seguir movi\xe9ndose en la direcci\xf3n de la sorpresa."},relative_strength:{title:"Fuerza relativa frente al sector",description:"Rentabilidad de la acci\xf3n menos la del ETF de su sector en el mismo periodo: dice si el movimiento es propio de la empresa o de todo su sector."},sector_etf:{title:"ETF del sector",description:"Fondo cotizado que re\xfane a las empresas grandes de un sector (XLK, tecnolog\xeda; XLF, financiero; XLV, salud; y as\xed con cada sector). Sirve de referencia para comparar la acci\xf3n con su sector."},pos52:{title:"Posici\xf3n en el rango de 52 semanas",description:"D\xf3nde cotiza el precio dentro de su rango del \xfaltimo a\xf1o. Es contexto de mercado: no dice si la acci\xf3n est\xe1 cara o barata ni mide la calidad del negocio.",formula:"(Precio − m\xednimo 52s) / (m\xe1ximo 52s − m\xednimo 52s)",tip:"El atractivo del precio sale de los m\xfaltiplos y del DCF, no de la posici\xf3n en el rango."},pe:{title:"P/E (precio / beneficio, TTM)",description:"Cu\xe1nto pagan los inversores por cada d\xf3lar de beneficio de los \xfaltimos doce meses.",formula:"Precio / BPA de los \xfaltimos 12 meses",good:"Un P/E por debajo de su referencia, con beneficios estables, puede indicar oportunidad.",bad:"Un P/E muy por encima de su referencia sin crecimiento que lo respalde sugiere sobrevaloraci\xf3n.",tip:"Se compara siempre con la mediana de su referencia (sector o mercado), nunca con un n\xfamero fijo."},pe_normalized:{title:"P/E normalizado",description:"P/E calculado sobre el beneficio sin partidas no recurrentes.",tip:"Se muestra cuando las partidas extraordinarias distorsionan el P/E reportado."},forward_pe:{title:"Forward P/E",description:"Precio dividido por el beneficio estimado para los pr\xf3ximos doce meses.",formula:"Precio / BPA estimado",good:"Por debajo del P/E actual: el mercado espera que el beneficio crezca.",bad:"Por encima del P/E actual: el mercado espera una ca\xedda del beneficio."},pb:{title:"P/B (precio / valor en libros)",description:"Compara el precio de mercado con el valor contable del patrimonio.",formula:"Precio / (patrimonio / acciones)",tip:"M\xe1s \xfatil en bancos y empresas intensivas en capital que en negocios de intangibles."},ptbv:{title:"P/TBV (precio / valor en libros tangible)",description:"Como el P/B, pero sin fondo de comercio ni intangibles: el patrimonio que respalda de verdad a un banco.",formula:"Capitalizaci\xf3n / patrimonio tangible"},ps:{title:"P/S (precio / ventas)",description:"Capitalizaci\xf3n dividida por los ingresos. \xdatil cuando a\xfan no hay beneficios.",formula:"Capitalizaci\xf3n / ingresos"},peg:{title:"PEG",description:"El P/E ajustado por el crecimiento esperado del beneficio.",formula:"P/E / crecimiento del beneficio (%)",tip:"Depende de estimaciones: si el crecimiento no llega, el PEG real ser\xe1 mayor."},ev_ebitda:{title:"EV/EBITDA",description:"Valor de la empresa (incluida la deuda neta) frente a su beneficio operativo antes de amortizaciones.",formula:"Enterprise value / EBITDA",tip:"Neutral a la estructura de capital: compara empresas con distinto endeudamiento."},ev_ebitda_normalized:{title:"EV/EBITDA normalizado",description:"EV/EBITDA sobre el EBITDA medio del ciclo, no sobre el de un a\xf1o concreto.",tip:"En empresas c\xedclicas el EBITDA de un a\xf1o puede estar en el pico o en el valle del ciclo."},pfcf:{title:"P/FCF (precio / flujo de caja libre)",description:"Cu\xe1nto se paga por cada d\xf3lar de caja libre que genera la empresa.",formula:"Capitalizaci\xf3n / flujo de caja libre"},p_fcf_normalized:{title:"P/FCF normalizado",description:"P/FCF sobre el flujo de caja libre de mantenimiento (flujo operativo − amortizaciones), promedio del ciclo."},fcf_yield:{title:"FCF yield",description:"Flujo de caja libre en relaci\xf3n con el valor de mercado: el inverso del P/FCF.",formula:"Flujo de caja libre / capitalizaci\xf3n",tip:"El flujo de caja es m\xe1s dif\xedcil de maquillar que el beneficio contable."},earnings_yield:{title:"Earnings yield (E/P)",description:"Beneficio por cada d\xf3lar invertido al precio actual: el inverso del P/E.",formula:"BPA / precio",tip:"Comp\xe1ralo con la rentabilidad del bono del Tesoro."},dividend_yield:{title:"Dividend yield",description:"Porcentaje del precio que la empresa devuelve cada a\xf1o en dividendos.",formula:"Dividendo anual por acci\xf3n / precio",bad:"Una rentabilidad anormalmente alta puede anticipar un recorte del dividendo."},p_ffo:{title:"P/FFO",description:"El m\xfaltiplo de referencia de los REIT: precio frente a los fondos de operaciones (beneficio + amortizaci\xf3n inmobiliaria).",formula:"Precio / FFO por acci\xf3n"},ev_sales:{title:"EV/Ventas",description:"Valor de la empresa frente a sus ingresos: el m\xfaltiplo de las compa\xf1\xedas que a\xfan no tienen beneficios.",formula:"Enterprise value / ingresos"},rule_of_40:{title:"Regla de 40",description:"Crecimiento de ingresos m\xe1s margen de flujo de caja libre (descontada la compensaci\xf3n en acciones en pre-beneficio).",formula:"Crecimiento de ingresos + margen (FCF − SBC)",tip:"Equilibra crecer r\xe1pido con generar caja."},dcf_upside:{title:"Valor justo DCF y potencial",description:"El DCF estima el valor de la empresa descontando sus flujos de caja futuros al coste de capital (WACC). El potencial es la distancia entre ese valor y el precio.",formula:"Σ FCF_t / (1 + WACC)^t + valor terminal descontado",tip:"Muy sensible al crecimiento y a la tasa de descuento: revisa la tabla de sensibilidad y la fiabilidad del DCF."},dcf_fair_value:{title:"Valor justo DCF",description:"Valor por acci\xf3n que estima el modelo DCF con el escenario base."},margin_of_safety:{title:"Margen de seguridad",description:"Distancia entre el valor intr\xednseco estimado y el precio, sobre el valor intr\xednseco. Concepto central de Benjamin Graham.",formula:"(Valor intr\xednseco − precio) / valor intr\xednseco"},graham:{title:"N\xfamero de Graham",description:"Referencia del inversor defensivo de Benjamin Graham: el precio m\xe1ximo que pagar\xeda con un P/E de 15 y un P/B de 1,5.",formula:"√(22,5 \xd7 BPA \xd7 valor en libros por acci\xf3n)",tip:"Es una referencia; no vota en la convergencia entre m\xe9todos de valoraci\xf3n."},sensitivity:{title:"Sensibilidad del valor justo",description:"C\xf3mo cambia el valor justo del DCF al variar el crecimiento (filas) y la tasa de descuento (columnas). El recuadro marca el escenario base.",tip:"F\xedjate en los escenarios conservadores: crecimiento bajo y descuento alto."},wacc:{title:"WACC (coste de capital)",description:"La rentabilidad m\xednima que la empresa debe generar para no destruir valor: el coste medio ponderado de su patrimonio y su deuda.",formula:"%patrimonio \xd7 Ke + %deuda \xd7 Kd \xd7 (1 − t)"},multiples_block:{title:"Bloque de m\xfaltiplos",description:"P/E, Forward P/E, P/FCF, EV/EBITDA y PEG est\xe1n correlacionados: punt\xfaan juntos, como un solo bloque. El ajuste individual de cada uno se muestra entre par\xe9ntesis."},roe:{title:"ROE (rentabilidad sobre el patrimonio)",description:"Cu\xe1nto beneficio genera la empresa por cada d\xf3lar de los accionistas.",formula:"Beneficio neto / patrimonio",bad:"Un ROE alto sostenido con mucha deuda es fr\xe1gil: revisa el apalancamiento."},rote:{title:"ROTE (rentabilidad sobre el patrimonio tangible)",description:"Beneficio por cada d\xf3lar de patrimonio sin contar el fondo de comercio ni otros intangibles. En bancos es la rentabilidad con la que se lee el precio sobre el valor en libros tangible (P/TBV).",formula:"Beneficio neto / patrimonio tangible"},roa:{title:"ROA (rentabilidad sobre activos)",description:"Eficiencia para generar beneficio con todos los recursos, propios y prestados.",formula:"Beneficio neto / activos totales",tip:"M\xe1s comparable que el ROE entre empresas con distinto endeudamiento."},roic:{title:"ROIC (rentabilidad sobre el capital invertido)",description:"Rentabilidad despu\xe9s de impuestos de todo el capital invertido en el negocio (patrimonio y deuda).",formula:"NOPAT / capital invertido",tip:"Cuando el capital invertido es muy peque\xf1o, el ROIC deja de ser significativo."},roic_wacc_spread:{title:"Spread ROIC − WACC (creaci\xf3n de valor)",description:"Diferencia entre lo que la empresa gana sobre su capital y lo que le cuesta. Positivo: crea valor; negativo: lo destruye.",formula:"ROIC − WACC"},roce:{title:"ROCE (rentabilidad sobre el capital empleado)",description:"Beneficio operativo antes de impuestos sobre el capital empleado (activos − pasivos corrientes).",formula:"EBIT / capital empleado"},roce_avg:{title:"ROCE promedio",description:"ROCE medio de los \xfaltimos ejercicios: la rentabilidad a lo largo del ciclo."},gross_margin:{title:"Margen bruto",description:"Lo que queda de cada d\xf3lar de ventas tras el coste directo de lo vendido: el poder de precios b\xe1sico.",formula:"(Ingresos − coste de ventas) / ingresos"},operating_margin:{title:"Margen operativo",description:"Lo que queda de cada d\xf3lar de ventas tras todos los gastos de operaci\xf3n.",formula:"Beneficio operativo / ingresos"},net_margin:{title:"Margen neto",description:"Lo que queda de cada d\xf3lar de ventas despu\xe9s de todos los gastos, intereses e impuestos.",formula:"Beneficio neto / ingresos"},runway:{title:"Runway",description:"A\xf1os que la caja cubre la quema de flujo de caja libre. Sustituye al Altman en las empresas pre-beneficio.",formula:"(Caja + inversiones a corto plazo) / quema anual de FCF"},current_ratio:{title:"Current ratio",description:"Capacidad de pagar las deudas a corto plazo con los activos corrientes.",formula:"Activos corrientes / pasivos corrientes"},quick_ratio:{title:"Quick ratio (prueba \xe1cida)",description:"Como el current ratio, pero sin inventarios, que pueden tardar en convertirse en caja.",formula:"(Activos corrientes − inventarios) / pasivos corrientes"},cash_ratio:{title:"Cash ratio",description:"La prueba de liquidez m\xe1s estricta: solo caja frente a los pasivos corrientes.",formula:"Caja y equivalentes / pasivos corrientes"},de:{title:"Deuda / patrimonio (D/E)",description:"D\xf3lares de deuda por cada d\xf3lar de patrimonio.",formula:"Deuda total / patrimonio",tip:"No mide lo mismo en todos los negocios: en bancos los dep\xf3sitos son pasivo y en REIT el apalancamiento se mide por la deuda neta/EBITDA."},debt_to_assets:{title:"Deuda / activos",description:"Porcentaje de los activos financiado con deuda.",formula:"Deuda total / activos totales"},net_cash:{title:"Caja neta",description:"La caja supera a la deuda total: la empresa no tiene deuda neta. Importe = caja − deuda total.",formula:"Caja − deuda total"},net_debt_to_ebitda:{title:"Deuda neta / EBITDA",description:"A\xf1os de EBITDA que har\xedan falta para pagar la deuda neta (deuda menos caja).",formula:"(Deuda total − caja) / EBITDA",tip:"Con EBITDA negativo la ratio no es significativa."},interest_coverage:{title:"Cobertura de intereses",description:"Cu\xe1ntas veces el beneficio operativo cubre el gasto por intereses.",formula:"EBIT / gasto por intereses",tip:"Con EBIT negativo y caja neta no es significativa: los intereses se pagan con caja."},payout_ratio:{title:"Payout",description:"Porcentaje del beneficio (en REIT, del FFO) que se reparte como dividendo.",formula:"Dividendos / beneficio neto (o FFO)",bad:"Un payout por encima del beneficio no es sostenible en el tiempo."},revenue_growth:{title:"Crecimiento de ingresos",description:"Tasa anual compuesta de los ingresos en los \xfaltimos 3 a\xf1os (en c\xedclicas, el promedio del ciclo; con diluci\xf3n o recompras relevantes, por acci\xf3n). Es la cifra que punt\xfaa Crecimiento."},revenue_growth_yoy:{title:"Crecimiento de ingresos (\xfaltimo ejercicio)",description:"Variaci\xf3n de los ingresos del \xfaltimo ejercicio anual frente al anterior, de los estados financieros. Es informativa: no punt\xfaa."},net_interest_income_growth:{title:"Margen de intereses (CAGR 3 a\xf1os)",description:"En un banco, lo que cobra por sus pr\xe9stamos menos lo que paga por sus dep\xf3sitos y su deuda: tasa anual compuesta de los \xfaltimos 3 a\xf1os y su peso en los ingresos netos. Es informativo: Crecimiento punt\xfaa los ingresos netos (margen de intereses m\xe1s comisiones)."},earnings_growth:{title:"Crecimiento del beneficio por acci\xf3n (BPA)",description:"Tasa anual compuesta del BPA en los \xfaltimos 3 a\xf1os (en c\xedclicas, el promedio del ciclo). Es la cifra que punt\xfaa Crecimiento."},earnings_growth_yoy:{title:"Crecimiento del BPA (\xfaltimo ejercicio)",description:"Variaci\xf3n del BPA diluido del \xfaltimo ejercicio anual frente al anterior, de los estados financieros. Es informativa: no punt\xfaa."},total_return:{title:"Retorno total por acci\xf3n (REIT)",description:"Rentabilidad por dividendo m\xe1s el crecimiento anual del FFO por acci\xf3n en los \xfaltimos 3 a\xf1os: el crecimiento que punt\xfaa en un REIT."},eps_vs_revenue:{title:"BPA frente a ingresos",description:"Diferencia entre el crecimiento del BPA y el de los ingresos: expansi\xf3n o compresi\xf3n de m\xe1rgenes (o efecto de recompras). Es informativo: no punt\xfaa."},buyback_yield:{title:"Buyback yield (recompras netas)",description:"Porcentaje de acciones retirado (o emitido) en el \xfaltimo a\xf1o.",formula:"(Acciones a\xf1o previo − acciones actuales) / acciones a\xf1o previo",bad:"Negativo: la empresa emite acciones y diluye a los accionistas."},shareholder_yield:{title:"Shareholder yield",description:"Todo lo que la empresa devuelve al accionista: dividendos m\xe1s recompras netas.",formula:"Dividend yield + buyback yield"},financial_health:{title:"Salud financiera (sector financiero)",description:"Puntuaci\xf3n de 0 a 10 de solidez para bancos y aseguradoras, donde el Altman no aplica: capitalizaci\xf3n, liquidez, calidad de activos y rentabilidad."},altman:{title:"Altman Z-Score",description:"Modelo de Edward Altman que estima el riesgo de insolvencia a dos a\xf1os. Finanzer elige la variante (Z, Z' o Z'') seg\xfan el sector exacto.",tip:"No se calcula con ceros: si falta un componente, queda \xabsin dato\xbb. No aplica a bancos ni a REIT."},piotroski:{title:"Piotroski F-Score",description:"Nueve se\xf1ales contables de mejora en rentabilidad, estructura de capital y eficiencia operativa (Joseph Piotroski, 2000).",tip:"Los criterios sin dato no cuentan como incumplidos: el resultado se escala sobre los evaluados."},breakdown:{title:"Desglose por categor\xeda",description:"Cada indicador suma o resta puntos a su categor\xeda seg\xfan la banda en la que cae; la columna de ajuste muestra cu\xe1nto."},alerts:{title:"Alertas y se\xf1ales",description:"Riesgos, advertencias y fortalezas que detecta el motor a partir de las m\xe9tricas.",tip:"Un riesgo pesa m\xe1s que varias fortalezas."},yearly:{title:"Hist\xf3rico anual",description:"Cifras de los estados anuales, los mismos con los que se calculan los crecimientos a 3 a\xf1os. Es dato bruto: sin lecturas ni colores."},free_cash_flow:{title:"Flujo de caja libre",description:"Caja que genera el negocio tras invertir en mantenerlo.",formula:"Flujo operativo − capex"},fcf_minus_sbc:{title:"FCF − SBC",description:"Flujo de caja libre descontada la compensaci\xf3n en acciones, que es un coste real pagado con diluci\xf3n."}};function n(e,a){return o[e]??{title:a,description:""}}}}]);